# Varicocele, testicular lumps, Klinefelter syndrome, teen health hub (Nov 2026, owner's request)
G = ["Men’s health"]
HM_LUMPS = ("Healthy Male: Lumps in the scrotum", "https://healthymale.org.au/mens-health/scrotal-lumps")

fact("varicocele",
 "Varicocele: Enlarged Veins in the Scrotum",
 "Varicocele: enlarged veins around the testicle, a ‘bag of worms’ feel. How common it is, link to low sperm count and fertility, when treatment helps, and surgery or embolisation.",
 "Varicocele", "varicocele",
 "Enlarged veins around a testicle, usually the left. About 1 in 5 men have one, and most never know or need treatment. It matters mainly when it causes pain, or when a couple is struggling to conceive and the semen test is abnormal.",
 h2("What it is", [
   "The veins that drain the testicle become stretched and swollen, like varicose veins in the leg.",
   "About 20 to 25% of adult men have one. Most are on the <b>left</b>, because of the way that vein drains.",
   "Large ones look or feel like a soft <b>‘bag of worms’</b> above the testicle, more obvious when standing and gone when lying down.",
   "Most cause no symptoms. Some cause a dull, dragging ache, worse after standing or exercise."]) +
 h2("Fertility", [
   "Varicoceles are more common in men with fertility problems. The leading theory is that the pooled blood warms the testicle.",
   "But fewer than half of men with a varicocele have lower sperm count or quality.",
   "In men with an abnormal semen test, repairing it improves the semen in about two-thirds. The effect on pregnancy rates is less certain."]) +
 h2("When treatment is considered", [
   "Ongoing pain or ache.",
   "Infertility with an abnormal semen test and a varicocele you can feel.",
   "In teenagers, if the testicle on that side is smaller or not growing properly.",
   "A varicocele only seen on ultrasound, with a normal semen test, usually doesn’t need treatment."]) +
 h2("Treatment", [
   "<b>Surgery</b> ties off the enlarged veins through a small cut in the groin, usually as a day procedure.",
   "<b>Embolisation:</b> a radiologist blocks the vein from inside with a tiny coil, through a vein in the groin or neck.",
   "Supportive underwear and pain relief can ease mild aches.",
   "Sperm take about 3 months to make, so semen tests are repeated 3 to 6 months after treatment."]) +
 h2("See a doctor promptly if", [
   "A varicocele appears suddenly in an older man, is only on the right, or doesn’t empty when lying down. These need a scan to check for something pressing on the veins.",
   "Any hard lump in the testicle itself."]),
 [("Is a varicocele serious?", "Usually not. Most cause no symptoms and need no treatment. It matters mainly for pain, or for fertility problems with an abnormal semen test."),
  ("Does a varicocele cause infertility?", "It can lower sperm count or quality in some men, but fewer than half of men with a varicocele have abnormal semen. Many father children without treatment."),
  ("Why is a varicocele usually on the left?", "The left testicle’s vein drains at a right angle into a larger vein, so pressure builds more easily. A new right-sided varicocele should be checked with a scan."),
  ("Does varicocele surgery improve sperm count?", "In men with an abnormal semen test, about two-thirds see improvement. The effect on pregnancy rates is less certain.")],
 [HM_LUMPS + ("Australian men’s health information. Free.",)],
 [("ReproductiveFacts (ASRM): Varicocele fact sheet", "https://www.reproductivefacts.org/news-and-publications/fact-sheets-and-infographics/varicocele-fact-sheet/"),
  HM_LUMPS],
 [("Low sperm count", "/low-sperm-count/"), ("Testicular lumps", "/testicular-lumps/"), ("Male infertility", "/male-infertility/")],
 groups=G, blurb="Enlarged veins around the testicle. Common, often harmless; matters for pain and fertility.",
 search="varicocele bag of worms scrotum enlarged veins testicle left testicle varicocelectomy embolisation male infertility low sperm count dragging ache")

fact("testicular-lumps",
 "Testicular Lumps and Self-Checks: What’s Normal and What Isn’t",
 "Testicular lumps: how to check your testicles, what’s normal, common harmless lumps (cysts, hydrocele, varicocele), testicular cancer signs, and the emergency of testicular torsion.",
 "Testicular Lumps and Self-Checks", "testicular lumps",
 "Most lumps in the scrotum aren’t cancer. But testicular cancer is the cancer of young men, and with 98% surviving five years, finding it early is the whole game. A monthly 2-minute check is all it takes.",
 h2("How to check", [
   "After a warm shower, when the skin is relaxed.",
   "Hold the scrotum in your palm. Roll each testicle gently between your thumb and fingers.",
   "A healthy testicle feels <b>firm and smooth</b>, like a hard-boiled egg without its shell.",
   "Normal: one testicle slightly bigger, the left hanging lower, and a soft, coiled tube at the back of each (the epididymis).",
   "Look for <b>a hard lump, swelling or change</b> from how it usually feels. Check monthly so you know your normal."]) +
 h2("Common harmless lumps", [
   "<b>Epididymal cyst:</b> a smooth, pea-sized fluid lump, separate from the testicle. Very common and harmless.",
   "<b>Hydrocele:</b> fluid around the testicle, making a soft, painless swelling. Can be drained or repaired if large.",
   "<b>Varicocele:</b> enlarged veins, like a ‘bag of worms’ above the testicle.",
   "<b>Inguinal hernia:</b> a bulge from the groin into the scrotum, often bigger when coughing or standing."]) +
 h2("Testicular cancer", [
   "About <b>1,040</b> Australians are diagnosed each year, with the peak at ages <b>30 to 34</b>. It’s one of the most common cancers in young men.",
   "Usually a <b>painless, hard lump or swelling</b> in the testicle, sometimes a dull ache or heaviness.",
   "Higher risk: an undescended testicle as a baby, a past testicular cancer, or a father or brother who had it.",
   "Treatment usually starts with removing the testicle. <b>98%</b> of men are alive five years after diagnosis.",
   "One remaining testicle usually makes enough testosterone and sperm. Sperm can be banked before treatment."]) +
 h2("When to act", [
   "<b>Any hard lump or change in a testicle:</b> see your GP soon. An ultrasound gives a quick answer.",
   "<b>Sudden, severe testicle pain</b>, often with nausea or vomiting, especially in teens: go to hospital now. This may be <b>testicular torsion</b>, where the testicle twists and loses its blood supply. Surgery within about 6 hours gives the best chance of saving it.",
   "A painful, red, swollen testicle with fever or burning when weeing: likely infection (epididymitis), so see a doctor the same day."]),
 [("How often should I check my testicles?", "Monthly is a good habit. The point is to know what’s normal for you, so you notice any change."),
  ("Is a lump on my testicle cancer?", "Most scrotal lumps aren’t cancer: cysts, fluid and veins are far more common. But a hard lump in the testicle itself needs checking with your GP, usually with an ultrasound."),
  ("What age does testicular cancer happen?", "It’s most common in young men, peaking at ages 30 to 34 in Australia, but it can happen at any age."),
  ("Is sudden testicle pain an emergency?", "Yes. Sudden, severe pain may be torsion, a twisted testicle. Go to hospital straight away: surgery within hours can save the testicle.")],
 [HM_LUMPS + ("Australian men’s health information. Free.",),
  ("Healthy Male: Testicular self-exam fact sheet", "https://wp.healthymale.org.au/wp-content/uploads/2024/05/Testicular-Self-Exam-Fact-Sheet-2019.pdf", "How to check. Free.")],
 [("Cancer Australia: Testicular cancer in Australia statistics", "https://www.canceraustralia.gov.au/cancer-types/testicular-cancer/testicular-cancer-australia-statistics"),
  HM_LUMPS,
  ("Healthy Male: Testicular self-exam fact sheet", "https://wp.healthymale.org.au/wp-content/uploads/2024/05/Testicular-Self-Exam-Fact-Sheet-2019.pdf"),
  ("Healthdirect: Surgery for benign scrotal lumps", "https://www.healthdirect.gov.au/surgery/surgery-for-benign-scrotal-lumps")],
 [("Varicocele", "/varicocele/"), ("Low testosterone", "/low-testosterone/"), ("Prostate cancer", "/prostate-cancer/")],
 groups=G, blurb="How to check, the common harmless lumps, cancer signs and the torsion emergency.",
 search="testicular lump testicle lump testicular cancer self exam check balls epididymal cyst hydrocele varicocele torsion testicle pain scrotum swelling")

fact("klinefelter-syndrome",
 "Klinefelter Syndrome (XXY): Signs, Diagnosis and Treatment",
 "Klinefelter syndrome (47,XXY): the most common chromosome difference in males, mostly undiagnosed. Signs at each age, diagnosis, testosterone treatment, fertility options and health checks.",
 "Klinefelter Syndrome (XXY)", "Klinefelter syndrome",
 "An extra X chromosome in males. It’s common, around 1 in 580 males, yet most are never diagnosed. Many first find out when trying for a baby. Testosterone treatment and support make a real difference at any age.",
 h2("What it is", [
   "Males usually have one X and one Y chromosome (XY). In Klinefelter syndrome there’s an extra X (<b>XXY</b>). It happens by chance, not from anything parents did.",
   "The testicles make less testosterone and usually little or no sperm.",
   "It varies a lot. Many have subtle features and live typical lives without knowing."]) +
 h2("Signs by age", [
   "<b>Childhood:</b> sometimes later walking or talking, learning or attention difficulties, low muscle tone, being tall.",
   "<b>Puberty:</b> small, firm testicles, less facial and body hair, some breast growth, long legs.",
   "<b>Adults:</b> infertility (often the first clue), low libido, tiredness, low mood, thinning bones."]) +
 h2("Diagnosis", [
   "A chromosome blood test (<b>karyotype</b>) confirms it.",
   "Hormone tests usually show low testosterone with high LH and FSH.",
   "Small testicles on examination are the most consistent sign, so a doctor’s exam matters."]) +
 h2("Treatment and support", [
   "<b>Testosterone</b>, usually started around puberty, supports puberty, energy, mood, muscle and bone. It’s usually lifelong.",
   "Speech, learning, occupational therapy and psychology support help children and teens who need it.",
   "Breast tissue that doesn’t settle can be removed surgically."]) +
 h2("Fertility", [
   "Most men with XXY have no sperm in their semen, but sperm can sometimes be found in the testicles with a surgical procedure (micro-TESE) and used for IVF with ICSI.",
   "Testosterone treatment lowers sperm production, so talk to a fertility specialist before or early in treatment if you want children."]) +
 h2("Long-term health", [
   "Higher risk of osteoporosis, type 2 diabetes, blood clots, heart disease, some autoimmune conditions and male breast cancer.",
   "Regular checks of bone density, weight, blood sugar and mood are worthwhile."]),
 [("How common is Klinefelter syndrome?", "It affects about 1 in 580 males, making it the most common chromosome difference in males. Most are never diagnosed."),
  ("Can men with Klinefelter syndrome have children?", "Some can, with help. Sperm can sometimes be retrieved from the testicles and used for IVF with ICSI. Talk to a fertility specialist early, ideally before starting testosterone."),
  ("Is Klinefelter syndrome inherited?", "Usually not. The extra X comes from a random event when the egg or sperm forms."),
  ("What is the treatment for Klinefelter syndrome?", "There’s no cure, but testosterone treatment, learning support and regular health checks help a lot.")],
 [("Healthy Male: Klinefelter syndrome diagnosis", "https://www.healthymale.org.au/news/klinefelter-syndrome-diagnosis", "Australian men’s health information. Free."),
  ("Healthdirect: Klinefelter (XXY) syndrome", "https://www.healthdirect.gov.au/amp/article/klinefelter-syndrome", "Free.")],
 [("Healthdirect: Klinefelter (XXY) syndrome", "https://www.healthdirect.gov.au/amp/article/klinefelter-syndrome"),
  ("Yeap BB et al. Endocrine Society of Australia position statement on male hypogonadism (part 1). Med J Aust 2016", "https://www.mja.com.au/journal/2016/205/4/endocrine-society-australia-position-statement-male-hypogonadism-part-1"),
  ("Better Health Channel: Androgen deficiency in men", "https://betterhealth.vic.gov.au/health/conditionsandtreatments/androgen-deficiency-in-men")],
 [("Low testosterone", "/low-testosterone/"), ("Low sperm count", "/low-sperm-count/"), ("22q11.2 deletion syndrome", "/22q11-deletion-syndrome/")],
 groups=G + ["Hormones"], blurb="An extra X in males: common, mostly undiagnosed, and very treatable.",
 search="klinefelter syndrome XXY 47 XXY extra X chromosome small testes infertility azoospermia testosterone micro-TESE tall boys gynaecomastia")

fact("teen-health",
 "Teen Health: A Guide for Teenagers and Parents",
 "A quick guide to common teen health problems: acne, periods, glandular fever, sports concussion, sleep, mental health, testicular checks, vaping and when to get help.",
 "Teen Health", "teen health",
 "The teenage years bring new health questions, many of them awkward to ask. Here are the common ones, what helps, and where to get confidential help. From age 15, teens can have their own Medicare card and see a GP on their own.",
 h2("Skin and body", [
   "<a href=\"/acne/\">Acne</a>: very common and very treatable. Don’t wait it out if it’s scarring or getting you down.",
   "<a href=\"/testicular-lumps/\">Testicular self-checks</a>: a monthly check. Sudden testicle pain is an emergency.",
   "<a href=\"/varicocele/\">Varicocele</a>: a ‘bag of worms’ above the testicle, usually harmless."]) +
 h2("Periods", [
   "<a href=\"/period-pain/\">Period pain</a>: some is normal; pain that stops school or sport isn’t, and can be <a href=\"/endometriosis/\">endometriosis</a>.",
   "<a href=\"/heavy-periods/\">Heavy periods</a>: changing pads or tampons every 1 to 2 hours, or flooding, needs checking for low iron or a bleeding problem.",
   "Irregular periods are common in the first couple of years. No periods by 15, or long gaps later, are worth a GP visit (<a href=\"/pcos/\">PCOS</a> is one cause)."]) +
 h2("Infections and injuries", [
   "<a href=\"/glandular-fever/\">Glandular fever</a>: sore throat, fever and big glands, with tiredness that can last weeks. No contact sport until a doctor says the spleen is safe.",
   "<a href=\"/concussion/\">Concussion</a>: if in doubt, sit them out. Under-19s need 14 symptom-free days before contact training and at least 21 days before contact games."]) +
 h2("Mind, sleep and habits", [
   "Teens need about 8 to 10 hours of sleep. Screens off an hour before bed helps.",
   "Low mood, anxiety, self-harm thoughts or eating worries: talk to a GP, school counsellor or headspace. You don’t need a parent’s permission.",
   "Vaping is addictive, and selling vapes to under-18s is illegal in Australia. Quitline (13 78 48) helps teens too."]) +
 h2("Get help", [
   "<b>Emergency:</b> call 000.",
   "<b>Kids Helpline:</b> 1800 55 1800, free and confidential, any time, for ages 5 to 25.",
   "<b>headspace:</b> free or low-cost mental health and GP services for ages 12 to 25.",
   "<b>Your GP:</b> from 14 or 15, you can usually see your GP on your own, and what you say is kept confidential unless someone’s safety is at risk."]),
 [("Can a teenager see a GP without their parents?", "Yes. From around 14 or 15, young people can usually see a GP on their own, and from 15 they can have their own Medicare card. What you discuss is confidential unless there’s a serious risk to safety."),
  ("When do teens need to see a doctor about periods?", "If periods stop you going to school or sport, you’re changing products every 1 to 2 hours, you have no periods by 15, or you feel faint or very tired."),
  ("How long should a teen sit out after a concussion?", "Under Australian guidelines, under-19s need 14 symptom-free days before contact training and at least 21 days before returning to contact games."),
  ("Where can teenagers get free mental health help?", "Kids Helpline (1800 55 1800) any time, headspace centres for ages 12 to 25, school counsellors, or a GP.")],
 [("Kids Helpline: 1800 55 1800", "https://kidshelpline.com.au/", "Free, confidential, 24/7 for ages 5 to 25."),
  ("headspace", "https://headspace.org.au/", "Mental and physical health support for ages 12 to 25.")],
 [("Australian Institute of Sport: Australian concussion guidelines for youth and community sport (2024)", "https://ausport.gov.au/winwell/news/australia-unites-with-nz-and-uk-on-world-leading-concussion-guidelines-to-improve-safety-for-kids-in-sport"),
  ("Royal Children’s Hospital Melbourne: Heavy periods, teens and young people", "https://www.rch.org.au/kidsinfo/fact_sheets/Heavy_periods_–_teens_and_young_people/"),
  ("Better Health Channel: Glandular fever", "https://betterhealth.vic.gov.au/health/conditionsandtreatments/glandular-fever"),
  ("Services Australia: Your own Medicare card from age 15", "https://www.servicesaustralia.gov.au/getting-your-own-medicare-card-when-youre-15-or-older")],
 [("Common newborn problems", "/newborn-problems/"), ("Acne", "/acne/"), ("Concussion", "/concussion/")],
 groups=["Babies and children"], blurb="Acne, periods, glandular fever, concussion, mental health and where teens can get help.",
 search="teen health teenager health problems adolescent health puberty teens see gp alone confidential acne periods concussion glandular fever mental health headspace kids helpline")
